use std::{fmt::Debug, marker::PhantomData};

pub struct Pair<'a, T: Clone> {
    left: &'a T,
    right: Option<T>,
}

enum State<T> {
    Ready(T),
    Waiting { retries: u32 },
    Done,
}

trait Convert<T> {
    type Error;
    fn convert(&self, value: T) -> Result<T, Self::Error>;
}

impl<'a, T: Clone + Debug> Pair<'a, T> {
    pub fn first(&self) -> &'a T {
        self.left
    }
}

fn flow(values: &[i32]) -> i32 {
    let mut total = 0;
    for value in values.iter() {
        total += match value {
            0 => 1,
            value if *value > 0 => *value,
            _ => continue,
        };
    }
    while total > 100 {
        total /= 2;
    }
    if total == 42 {
        return total;
    }
    total
}

